                {
                  tmp_acc += A[i][j] * x[j];
                  y_acc += B[i][j] * x[j];
                }
            }

          tmp[i] = tmp_acc;
          y[i] = alpha * tmp_acc + beta * y_acc;
        }
    }
#pragma endscop

}


